composition:
@media (min-width: 1100px) {
  :root[data-layout="enterprise"] body:not(:has(.admin-portal-root)) { display: grid; grid-template-columns: 224px minmax(0, 1fr); }
  :root[data-layout="enterprise"] body:not(:has(.admin-portal-root)) > .site-header { grid-column: 1 / -1; }
  :root[data-layout="enterprise"] body:not(:has(.admin-portal-root)) > #main-content,
  :root[data-layout="enterprise"] body:not(:has(.admin-portal-root)) > .site-footer { grid-column: 2; min-width: 0; }
  :root[data-layout="enterprise"] .shell { width: min(1180px, calc(100% - 48px)); }
  :root[data-layout="enterprise"] .site-header .header-inner { width: calc(100% - 48px); min-height: 84px; grid-template-columns: 200px 1fr auto; }
  :root[data-layout="enterprise"] .site-header .header-actions { grid-column: 3; }
  :root[data-layout="enterprise"] .site-header nav { position: fixed; inset: 84px auto auto 0; width: 224px; height: calc(100dvh - 84px); overflow-y: auto; overscroll-behavior: contain; padding: 28px 20px; display: flex; flex-direction: column; align-items: stretch; justify-content: flex-start; gap: 12px; }
  :root[data-layout="enterprise"] .site-header nav > a,
  :root[data-layout="enterprise"] .site-header nav > .header-menu > .header-menu-trigger { justify-content: flex-start; width: 100%; }
  :root[data-layout="enterprise"] .site-header nav > a.nav-cta { display: none; }
  :root[data-layout="enterprise"] .site-header nav .header-menu-panel { position: static; width: 100%; max-width: 100%; }
}
